app.post('/webhooks/stripe',
  express.raw({ type: 'application/json' }),   // keep the RAW body
  (req, res) => {
    const signature = req.headers['stripe-signature'];
    let event;
    try {
      event = stripe.webhooks.constructEvent(req.body, signature, endpointSecret);
    } catch (err) {
      return res.status(400).send('invalid signature'); // reject spoofed calls
    }

    queue.add(event);            // hand off to a background worker
    res.status(200).send('ok');  // acknowledge fast
  });

